107	fn schema_root() -> Result<PathBuf> {
108	    // In Bazel runfiles (especially manifest-only mode), resolving directories is not
109	    // reliable. Resolve a known file, then walk up to the schema root.
110	    let typescript_index = codex_utils_cargo_bin::find_resource!("schema/typescript/index.ts")
111	        .context("resolve TypeScript schema index.ts")?;
112	    let schema_root = typescript_index
113	        .parent()
114	        .and_then(|p| p.parent())
115	        .context("derive schema root from schema/typescript/index.ts")?
116	        .to_path_buf();
117	
118	    // Sanity check that the JSON fixtures resolve to the same schema root.
119	    let json_bundle =
120	        codex_utils_cargo_bin::find_resource!("schema/json/codex_app_server_protocol.schemas.json")
121	            .context("resolve JSON schema bundle")?;
122	    let json_root = json_bundle
123	        .parent()
124	        .and_then(|p| p.parent())
125	        .context("derive schema root from schema/json/codex_app_server_protocol.schemas.json")?;
126	    anyhow::ensure!(
127	        schema_root == json_root,
128	        "schema roots disagree: typescript={} json={}",
129	        schema_root.display(),
130	        json_root.display()
131	    );
132	
133	    Ok(schema_root)
134	}
